Here is the commit message:
KVM: SEV: Lock all vCPUs when synchronzing VMSAs for SNP
 launch finish

Lock all vCPUs when synchronizing and encrypting VMSAs for SNP guests, as
allowing userspace to manipulate and/or run a vCPU while its state is being
synchronized would at best corrupt vCPU state, and at worst crash the host
kernel.

Opportunistically assert that vcpu->mutex is held when synchronizing its
VMSA (the SEV-ES path already locks vCPUs).

Fixes: ad27ce155566 ("KVM: SEV: Add KVM_SEV_SNP_LAUNCH_FINISH command")
Cc: stable@vger.kernel.org
Link: https://patch.msgid.link/20260310234829.2608037-6-seanjc@google.com
Signed-off-by: Sean Christopherson <seanjc@google.com>

Here is the root cause:
The bug is caused by missing vCPU locking when synchronizing and encrypting VMSAs for SNP guests during the KVM_SEV_SNP_LAUNCH_FINISH command. Without locking all vCPUs, userspace could manipulate or run a vCPU concurrently while its VMSA state is being synchronized, leading to vCPU state corruption or host kernel crash.

Here is the patch:

 static int sev_es_sync_vmsa(struct vcpu_svm *svm)
 {
 	struct kvm_vcpu *vcpu = &svm->vcpu;
 	struct kvm_sev_info *sev = to_kvm_sev_info(vcpu->kvm);
 	struct sev_es_save_area *save = svm->sev_es.vmsa;
 	struct xregs_state *xsave;
 	const u8 *s;
 	u8 *d;
 	int i;

+	lockdep_assert_held(&vcpu->mutex);
+
 	if (vcpu->arch.guest_state_protected)
 		return -EINVAL;

 	/* Check some debug related fields before encrypting the VMSA */
 	if (svm->vcpu.guest_debug || (svm->vmcb->save.dr7 & ~DR7_FIXED_1))
 		return -EINVAL;

 	/*
 	 * SEV-ES will use a VMSA that is pointed to by the VMCB, not
 	 * the traditional VMSA that is part of the VMCB. Copy the
 	 * traditional VMSA as it has been built so far (in prep
 	 * for LAUNCH_UPDATE_VMSA) to be the initial SEV-ES state.
 	 */
 	memcpy(save, &svm->vmcb->save, sizeof(svm->vmcb->save));

 	/* Sync registgers */
 	save->rax = svm->vcpu.arch.regs[VCPU_REGS_RAX];
 	save->rbx = svm->vcpu.arch.regs[VCPU_REGS_RBX];
 	save->rcx = svm->vcpu.arch.regs[VCPU_REGS_RCX];
 	save->rdx = svm->vcpu.arch.regs[VCPU_REGS_RDX];
 	save->rsp = svm->vcpu.arch.regs[VCPU_REGS_RSP];
 	save->rbp = svm->vcpu.arch.regs[VCPU_REGS_RBP];
 	save->rsi = svm->vcpu.arch.regs[VCPU_REGS_RSI];
 	save->rdi = svm->vcpu.arch.regs[VCPU_REGS_RDI];
 #ifdef CONFIG_X86_64
 	save->r8  = svm->vcpu.arch.regs[VCPU_REGS_R8];
 	save->r9  = svm->vcpu.arch.regs[VCPU_REGS_R9];
 	save->r10 = svm->vcpu.arch.regs[VCPU_REGS_R10];
 	save->r11 = svm->vcpu.arch.regs[VCPU_REGS_R11];
 	save->r12 = svm->vcpu.arch.regs[VCPU_REGS_R12];
 	save->r13 = svm->vcpu.arch.regs[VCPU_REGS_R13];
 	save->r14 = svm->vcpu.arch.regs[VCPU_REGS_R14];
 	save->r15 = svm->vcpu.arch.regs[VCPU_REGS_R15];
 #endif
 	save->rip = svm->vcpu.arch.regs[VCPU_REGS_RIP];

 	/* Sync some non-GPR registers before encrypting */
 	save->xcr0 = svm->vcpu.arch.xcr0;
 	save->pkru = svm->vcpu.arch.pkru;
 	save->xss  = svm->vcpu.arch.ia32_xss;
 	save->dr6  = svm->vcpu.arch.dr6;

 	save->sev_features = sev->vmsa_features;

 	/*
 	 * Skip FPU and AVX setup with KVM_SEV_ES_INIT to avoid
 	 * breaking older measurements.
 	 */
 	if (vcpu->kvm->arch.vm_type != KVM_X86_DEFAULT_VM) {
 		xsave = &vcpu->arch.guest_fpu.fpstate->regs.xsave;
 		save->x87_dp = xsave->i387.rdp;
 		save->mxcsr = xsave->i387.mxcsr;
 		save->x87_ftw = xsave->i387.twd;
 		save->x87_fsw = xsave->i387.swd;
 		save->x87_fcw = xsave->i387.cwd;
 		save->x87_fop = xsave->i387.fop;
 		save->x87_ds = 0;
 		save->x87_cs = 0;
 		save->x87_rip = xsave->i387.rip;

 		for (i = 0; i < 8; i++) {
 			/*
 			 * The format of the x87 save area is undocumented and
 			 * definitely not what you would expect.  It consists of
 			 * an 8*8 bytes area with bytes 0-7, and an 8*2 bytes
 			 * area with bytes 8-9 of each register.
 			 */
 			d = save->fpreg_x87 + i * 8;
 			s = ((u8 *)xsave->i387.st_space) + i * 16;
 			memcpy(d, s, 8);
 			save->fpreg_x87[64 + i * 2] = s[8];
 			save->fpreg_x87[64 + i * 2 + 1] = s[9];
 		}
 		memcpy(save->fpreg_xmm, xsave->i387.xmm_space, 256);

 		s = get_xsave_addr(xsave, XFEATURE_YMM);
 		if (s)
 			memcpy(save->fpreg_ymm, s, 256);
 		else
 			memset(save->fpreg_ymm, 0, 256);
 	}

 	pr_debug("Virtual Machine Save Area (VMSA):\n");
 	print_hex_dump_debug("", DUMP_PREFIX_NONE, 16, 1, save, sizeof(*save), false);

 	return 0;
 }


 static int snp_launch_update_vmsa(struct kvm *kvm, struct kvm_sev_cmd *argp)
 {
 	struct kvm_sev_info *sev = to_kvm_sev_info(kvm);
 	struct sev_data_snp_launch_update data = {};
 	struct kvm_vcpu *vcpu;
 	unsigned long i;
 	int ret;

 	if (kvm_is_vcpu_creation_in_progress(kvm))
 		return -EBUSY;

+	ret = kvm_lock_all_vcpus(kvm);
+	if (ret)
+		return ret;
+
 	data.gctx_paddr = __psp_pa(sev->snp_context);
 	data.page_type = SNP_PAGE_TYPE_VMSA;

 	kvm_for_each_vcpu(i, vcpu, kvm) {
 		struct vcpu_svm *svm = to_svm(vcpu);
 		u64 pfn = __pa(svm->sev_es.vmsa) >> PAGE_SHIFT;

 		ret = sev_es_sync_vmsa(svm);
 		if (ret)
-			return ret;
+			goto out;

 		/* Transition the VMSA page to a firmware state. */
 		ret = rmp_make_private(pfn, INITIAL_VMSA_GPA, PG_LEVEL_4K, sev->asid, true);
 		if (ret)
-			return ret;
+			goto out;

 		/* Issue the SNP command to encrypt the VMSA */
 		data.address = __sme_pa(svm->sev_es.vmsa);
 		ret = __sev_issue_cmd(argp->sev_fd, SEV_CMD_SNP_LAUNCH_UPDATE,
 				      &data, &argp->error);
 		if (ret) {
 			snp_page_reclaim(kvm, pfn);

-			return ret;
+			goto out;
 		}

 		svm->vcpu.arch.guest_state_protected = true;
 		/*
 		 * SEV-ES (and thus SNP) guest mandates LBR Virtualization to
 		 * be _always_ ON. Enable it only after setting
 		 * guest_state_protected because KVM_SET_MSRS allows dynamic
 		 * toggling of LBRV (for performance reason) on write access to
 		 * MSR_IA32_DEBUGCTLMSR when guest_state_protected is not set.
 		 */
 		svm_enable_lbrv(vcpu);
 	}

-	return 0;
+out:
+	kvm_unlock_all_vcpus(kvm);
+	return ret;
 }



